-- ============================================================================
-- Seed: the NorCal SCI mentor directory
-- ============================================================================
-- 23 members, seeded so the Peers deck demonstrates anything at all — an empty
-- deck hides every layout, filter and empty-state bug there is.
--
-- ---------------------------------------------------------------------------
-- Where this data comes from
-- ---------------------------------------------------------------------------
-- NorCal SCI's peer mentor directory, used with their permission. These are
-- real people. That fact governs everything below:
--
--   * Nothing is invented. Where the directory is silent, the column is null.
--     Injury dates in particular are absent from the source and are NOT
--     synthesized — a plausible-looking date we made up would be
--     indistinguishable from one the person gave us, and every screen that
--     reads it would be asserting a medical fact about somebody on our say-so.
--   * Phone numbers are reserved 555 placeholders. The directory carries no
--     numbers; the column is not null only because it is sign-in identity for
--     real members.
--   * Birth dates are 1 January of the year implied by the age the directory
--     gives. That reproduces the age exactly and claims nothing more.
--   * Gender is null throughout. The source carries an undocumented flag on six
--     entries which is read nowhere; no gender is inferred from it.
--
-- ---------------------------------------------------------------------------
-- Mentors
-- ---------------------------------------------------------------------------
-- Every person in this directory is in fact a NorCal SCI peer mentor. Five are
-- marked `mentor` here and the rest `peer`, so both sides of the Peers deck
-- have somebody in them. The five were drawn with a fixed seed, so the pick is
-- reproducible rather than different on every regeneration.
--
-- ---------------------------------------------------------------------------
-- Ids, and re-running
-- ---------------------------------------------------------------------------
-- Each id is derived from the person's name, so the same person always becomes
-- the same row. With `on conflict (id) do nothing` this migration is a no-op
-- against a database that already has it.
--
-- These ids belong to no auth account, so every policy on `members`
-- (`auth.uid() = id`) rejects writes to them from every caller: readable
-- through browse_members, writable by nobody.
--
-- `is_seed` marks them. If one of these people later joins for real, that flag
-- is how their own row gets reconciled with this one instead of sitting beside
-- it as a duplicate.
--
-- ---------------------------------------------------------------------------
-- Photos
-- ---------------------------------------------------------------------------
-- `photo_url` still points at NorCal SCI's own CDN. A later step copies these
-- into our `photos` bucket and rewrites the column: an app should not depend on
-- another organization's bandwidth or URL structure staying put.
-- ============================================================================

insert into public.members (
  id,
  type,
  display_name,
  phone,
  birth_date,
  level_range,
  exact_level,
  completeness,
  injury_date,
  injury_date_precision,
  city,
  state,
  photo_url,
  bio,
  gender,
  languages,
  independence,
  employment,
  field_of_work,
  education,
  marital_status,
  has_children,
  interests,
  topics,
  self_care,
  affiliations,
  wants_to_mentor,
  is_seed
) values
  ('c85c10bf-0226-394f-8c91-2a2ffc40a147', 'peer', 'Ajay', '15555550000', '1996-01-01', 'C5–C8', 'C7', 'Incomplete', null, null, 'San Jose', 'CA', 'https://images.squarespace-cdn.com/content/v1/639f51bcb6f2d126acbc35ab/76946e11-5bef-4527-999b-9691cf49e418/Ajay.jpg?format=500w', 'Manual chair. Strong upper body, weaker left tricep/lat/chest, impaired hand function (stronger grip right hand). Global spasticity used for hand function, transfers, and walking short distances with spotters. Lives alone.', null, array['English']::text[], 'Completely independent', 'Student', 'Nutrition (in grad school)', 'In progress — grad school for nutrition', null, null, array['Water sports', 'Fitness & exercise', 'Cooking']::text[], array['Adaptive sports', 'Back to school', 'Suprapubic catheter', 'UTIs', 'Getting into dating']::text[], array['Suprapubic catheter', 'Wheelchair assist devices']::text[], array['NorCal SCI']::text[], false, true),
