  ('43bb63c6-939e-461e-264c-4b2a817beb91', 'peer', 'Dante', '15555550002', '1997-01-01', 'C1–C4', 'C4', 'Incomplete', null, null, 'Aptos', 'CA', 'https://images.squarespace-cdn.com/content/v1/639f51bcb6f2d126acbc35ab/c1874d1d-6393-4625-9f20-eeb7ad0ee156/reevefoundationphoto.jpg?format=500w', 'No assistive devices; sometimes an AFO on the left leg. Good return of function in all four limbs. Lives at home with parents but is physically independent.', null, array['English']::text[], 'Completely independent', 'Full time', 'Freelance photographer (previously accounting)', 'BS Business Administration', null, null, array['Cycling', 'Photography', 'Mountain biking']::text[], array['Back to school', 'Being injured as a teen', 'Navigating walking again', 'Adaptive cycling']::text[], '{}', array['NorCal SCI']::text[], false, true),
