  ('11712b50-bf2e-3c6b-f736-250e96e6987f', 'peer', 'Gretchen', '15555550004', '1991-01-01', 'C5–C8', 'C5/6', 'Incomplete', null, null, 'Clovis', 'CA', 'https://images.squarespace-cdn.com/content/v1/639f51bcb6f2d126acbc35ab/fd970ac9-4ba3-478e-8879-b32440c372ea/Gretchen.JPG?format=500w', 'Manual chair with SmartDrive power assist. Can stand and use a walker short distances around the house. Lives with parents. Working with vocational rehab to find a full-time job.', null, array['English']::text[], 'Mostly independent', 'Seeking work', 'Medicine', 'Medical school graduate', null, null, array['Travel', 'Reading', 'Gardening']::text[], array['Advocacy', 'Travel', 'Neurogenic bladder and Botox', 'Mental health', 'Adaptive home improvements']::text[], array['Botox', 'Wheelchair assist devices']::text[], array['NorCal SCI']::text[], false, true),
  ('f2851f46-8fc1-ab8d-842c-33b7ceaccc9d', 'mentor', 'Jan', '15555550005', '1962-01-01', 'T7–T12', 'T12', 'Complete', null, null, 'Santa Cruz', 'CA', 'https://images.squarespace-cdn.com/content/v1/639f51bcb6f2d126acbc35ab/e62b8066-8eb5-4a2b-b1d5-6baa220f7d10/Jan+Edwards.jpeg?format=500w', 'Mostly manual with SmartDrive. Shoulder surgeries and arthritis have led to some upper body weakness. Paralympian and marathon participant post-injury. Sits on the board of a camp for kids and adults with disabilities and holds a leadership role in Canine Companions. Retired, lives with her husband.', null, array['English']::text[], 'Completely independent', 'Retired', 'Accounting (CPA)', 'BA Accounting, CPA', 'Married or partnered', null, array['Water sports', 'Camping & outdoors', 'Individual sports']::text[], array['Athletics and adaptive sports equipment', 'Other adaptive equipment', 'Self and suprapubic cath', 'Pain management', 'Pregnancy with paraplegia', 'Medical write-offs']::text[], array['Suprapubic catheter', 'Intermittent catheterization', 'Wheelchair assist devices', 'Service animals']::text[], array['NorCal SCI', 'Canine Companions']::text[], true, true),
