  ('4574f3e5-f615-d38a-80ba-2fef00000ade', 'peer', 'Tiffany', '15555550019', '1973-01-01', 'C5–C8', 'C5/6', 'Complete', null, null, 'Sacramento', 'CA', 'https://images.squarespace-cdn.com/content/v1/639f51bcb6f2d126acbc35ab/7b8f8576-f344-4c67-a9de-3d1650d90039/Poland_Headshot+%281%29.JPG?format=500w', 'Power chair. Has a hospital bed and an alternating pressure relief mattress. Has biceps but no triceps; uses typing aids and Dragon at times to write with her voice. Runs and attends several peer support groups including a monthly women''s group on Zoom. Lives with her mother, who is her full-time caregiver.', null, array['English']::text[], 'Partially dependent', 'Student', 'Human services', 'AA Human Services; working toward a BA in Disability Studies', null, null, array['Performing arts', 'Concerts', 'Comedy']::text[], array['Going back to school', 'Returning to college', 'Canine Companions']::text[], array['Dictation software', 'Service animals', 'Wheelchair assist devices']::text[], array['NorCal SCI', 'Canine Companions']::text[], false, true),
  ('9e79bac7-c43a-05b0-930e-2402417bdbf5', 'mentor', 'Todd', '15555550020', '1970-01-01', 'T7–T12', 'T12', 'Complete', null, null, 'Roseville', 'CA', 'https://images.squarespace-cdn.com/content/v1/639f51bcb6f2d126acbc35ab/acede200-8379-426d-9c5a-f4d99c787bde/Facetune_20-05-2024-17-21-09.png?format=500w', 'Manual chair; almost full upper body function. Lives with his wife and child.', null, array['English']::text[], 'Completely independent', 'Full time', 'Urology and rehab (30 years)', 'College educated', 'Married or partnered', true, array['Ski & snowboard', 'Winter sports', 'Photography']::text[], array['Adaptive sports', 'Sex', 'Infertility', 'Urology and urology products', 'Nutrition', 'Driving']::text[], array['Intermittent catheterization', 'Vehicle modifications']::text[], array['NorCal SCI']::text[], true, true),
  ('ccaae582-c2e5-14f8-a97d-bb501693acd7', 'peer', 'Vicki', '15555550021', '1953-01-01', 'C5–C8', 'C5/6', 'Incomplete', null, null, 'Eureka', 'CA', 'https://images.squarespace-cdn.com/content/v1/639f51bcb6f2d126acbc35ab/d2cf5730-9e60-484d-8fc7-3030b0ded91e/Vicki+Butler.jpeg?format=500w', 'Power chair; hand and arm function, no grip, no leg function. Retired; lives with her husband, married 40 years.', null, array['English']::text[], 'Partially dependent', 'Retired', 'State road maintenance; safety officer', 'High school graduate, some college', 'Married or partnered', null, array['Gardening', 'Quilting', 'Weaving']::text[], array['Adaptive equipment', 'Suprapubic tube', 'Colostomy', 'Osteoporosis']::text[], array['Suprapubic catheter', 'Colostomy']::text[], array['NorCal SCI']::text[], false, true),
